using System;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 // Persistent lab slots: only their live text/progress changes on ticks.
 public sealed class ResearchLabOverview:MonoBehaviour {
  float next;GameRuntime game;int count=-1;Text heading;Transform slots;Text[] status;Image[] progress;
  Button[] groups;ActionCard[] cards;int area;
  public void Bind(ActionCard[] entries,int selected){cards=entries;var tabs=WorkshopUIFactory.Node("ResearchAreas",transform,typeof(GridLayoutGroup),typeof(ItemGrid));WorkshopUIFactory.Size(tabs,92);var grid=tabs.GetComponent<GridLayoutGroup>();grid.constraint=GridLayoutGroup.Constraint.FixedColumnCount;grid.constraintCount=3;grid.spacing=new Vector2(4,4);tabs.GetComponent<ItemGrid>().Height=44;groups=new Button[5];for(int i=0;i<5;i++){int a=i;groups[i]=WorkshopUIFactory.Button("ResearchArea"+i,tabs.transform,"",()=>game.SetResearchArea(a));GameTheme.CompactAction(groups[i],false);}ShowArea(selected);}
  public void ShowArea(int selected){area=selected;if(cards==null)return;for(int i=0;i<cards.Length;i++)cards[i].gameObject.SetActive(Workshop.ResearchArea(Balance.Research[i].Id)==area);for(int i=0;i<groups.Length;i++){groups[i].GetComponentInChildren<Text>().text=UiLocalizedText.Translate(new[]{"Daten","Hardware","Modelle","Material","Automation"}[i],game.State.Settings.language);groups[i].GetComponentInChildren<Text>().color=i==area?GameTheme.Accent:GameTheme.Muted;groups[i].GetComponent<Image>().color=i==area?GameTheme.Hex("17353F"):Color.clear;}}
  public void Initialize(GameRuntime runtime){game=runtime;heading=WorkshopUIFactory.Label("ResearchHeading",transform,"",18,30);heading.font=GameTheme.Bold;slots=WorkshopUIFactory.Vertical("LaboratorySlots",transform).transform;Refresh();}
  void Update(){if(game!=null&&Time.unscaledTime>=next){next=Time.unscaledTime+.1f;Refresh();}}
  void Refresh(){var s=game.State;bool de=s.Settings.language=="de";var jobs=PrestigeAutomation.ResearchJobs(s).ToArray();int capacity=PrestigeAutomation.LabCount(s);heading.text=(de?"Forschung":"Research")+" · "+jobs.Length+" / "+capacity+(de?" belegt":" busy");int visible=Math.Max(capacity,jobs.Select(j=>j.slot+1).DefaultIfEmpty(0).Max());if(count!=visible){count=visible;WorkshopUIFactory.Clear(slots);status=new Text[count];progress=new Image[count];for(int i=0;i<count;i++){int slot=i;var row=WorkshopUIFactory.Horizontal("LabSlot"+i,slots,48);var surface=row.AddComponent<Image>();surface.color=GameTheme.Surface;surface.raycastTarget=false;status[i]=WorkshopUIFactory.Label("Status",row.transform,"",13,44);status[i].GetComponent<LayoutElement>().flexibleWidth=1;var button=row.AddComponent<Button>();button.onClick.AddListener(()=>{var current=PrestigeAutomation.ResearchJobs(game.State).ToArray();var job=current.FirstOrDefault(j=>j.slot==slot);if(job!=null)game.ShowDetails("research",Game.ResearchIndex(job.id));});var fill=WorkshopUIFactory.Node("Progress",row.transform,typeof(Image),typeof(LayoutElement));fill.GetComponent<LayoutElement>().ignoreLayout=true;progress[i]=fill.GetComponent<Image>();progress[i].raycastTarget=false;progress[i].sprite=GameTheme.Rounded;progress[i].type=Image.Type.Filled;progress[i].fillMethod=Image.FillMethod.Horizontal;progress[i].color=GameTheme.Accent;var r=(RectTransform)fill.transform;r.anchorMin=Vector2.zero;r.anchorMax=new Vector2(1,0);r.pivot=Vector2.zero;r.sizeDelta=new Vector2(0,3);}}
   for(int i=0;i<count;i++){var job=jobs.FirstOrDefault(j=>j.slot==i);status[i].transform.parent.gameObject.SetActive(i<capacity||job!=null);status[i].text=(de?"Labor ":"Lab ")+(i+1)+" · "+(i>=capacity?(de?"Abschluss · ":"Finishing · "):"")+(job==null?(de?"Frei":"Available"):SettingsRules.Text(s.Settings.language,"research:"+job.id)+" · "+Math.Ceiling(Math.Max(0,(job.required-job.done)/(job.intro?1:Game.ResearchSpeed(s,job))))+" s");status[i].color=job==null?GameTheme.Muted:GameTheme.Text;progress[i].fillAmount=job==null?0:(float)Math.Min(1,job.done/job.required);}
  }
 }
}
